$pdo->prepare('INSERT INTO modifier_options (tenant_id,group_id,name,price_delta_cents,cost_cents,inventory_quantity,production_enabled,sort_order,active) VALUES (?,?,?,300,0,0,0,1,1)')->execute([$tenantId,$extraGroup,'Queijo extra']);$cheese=(int)$pdo->lastInsertId();
