$send=function(string$text,string$phone='5511999998877',?string$id=null,string$name='Cliente Conhecido')use($commerce,$deviceId,&$seq):array{$seq++;return $commerce->receiveInbound($deviceId,['provider_message_id'=>$id??('CI.ST1.'.$seq.'.'.bin2hex(random_bytes(3))),'phone'=>$phone,'name'=>$name,'message_type'=>'text','text'=>$text,'timestamp'=>time(),'payload'=>[]]);};

$send('menu');$startId='CI.ST1.START.'.bin2hex(random_bytes(4));$start=$send('1','5511999998877',$startId);wa1_assert(($start['state']??'')==='SELECTING_CATEGORY','1 não abriu categorias.');
$q=$pdo->prepare('SELECT c.customer_id,c.draft_order_id,o.status,o.order_source,o.channel,o.unit_id FROM whatsapp_conversations c JOIN orders o ON o.id=c.draft_order_id WHERE c.tenant_id=? AND c.phone=?');$q->execute([$tenantId,'5511999998877']);$draft=$q->fetch(PDO::FETCH_ASSOC);wa1_assert(is_array($draft),'Draft normal não foi criado.');wa1_assert((int)$draft['customer_id']===$customerId,'Cliente conhecido não foi identificado pelo telefone.');wa1_assert($draft['status']==='draft'&&$draft['order_source']==='WHATSAPP'&&$draft['channel']==='pending','Origem/canal/status do draft estão incorretos.');wa1_assert((int)$draft['unit_id']===$unitId,'Draft não foi vinculado à unidade ativa.');$draftId=(int)$draft['draft_order_id'];
$dup=$send('1','5511999998877',$startId);wa1_assert(!empty($dup['duplicate']),'Mensagem duplicada não foi ignorada.');$q=$pdo->prepare('SELECT COUNT(*) FROM orders WHERE tenant_id=? AND order_source="WHATSAPP"');$q->execute([$tenantId]);wa1_assert((int)$q->fetchColumn()===1,'Mensagem duplicada criou pedido adicional.');

wa1_assert(($send('1')['state']??'')==='SELECTING_PRODUCT','Categoria não abriu produtos.');wa1_assert(($send('2')['state']??'')==='SELECTING_VARIANT','Produto configurado não abriu variação obrigatória.');wa1_assert(($send('2')['state']??'')==='SELECTING_ADDONS','Tamanho não avançou para adicionais.');$send('1');$send('2');wa1_assert(($send('ok')['state']??'')==='SELECTING_QUANTITY','Adicionais não avançaram para quantidade.');wa1_assert(($send('2')['state']??'')==='ENTERING_NOTE','Quantidade não avançou para observação.');wa1_assert(($send('sem cebola')['state']??'')==='CART','Item não entrou no carrinho.');
$q=$pdo->prepare('SELECT unit_price_cents,quantity,total_cents,notes FROM order_items WHERE order_id=? ORDER BY id LIMIT 1');$q->execute([$draftId]);$item=$q->fetch(PDO::FETCH_ASSOC);wa1_assert((int)$item['unit_price_cents']===3200&&(int)$item['quantity']===2&&(int)$item['total_cents']===6400,'Preço/quantidade do item configurado divergiu.');wa1_assert($item['notes']==='sem cebola','Observação não foi persistida.');$q=$pdo->prepare('SELECT COUNT(*) FROM order_item_modifiers WHERE tenant_id=? AND order_id=?');$q->execute([$tenantId,$draftId]);wa1_assert((int)$q->fetchColumn()===3,'Variação e adicionais não foram persistidos na estrutura normal.');

// Carrinho abandonado/reentrada: sair para MENU não pode apagar o draft nem os itens.
$send('menu');$resume=$send('meu pedido');wa1_assert(($resume['state']??'')==='CART','Carrinho abandonado não foi retomado pela conversa persistente.');$q=$pdo->prepare('SELECT COUNT(*) FROM order_items WHERE order_id=?');$q->execute([$draftId]);wa1_assert((int)$q->fetchColumn()===1,'Reentrada apagou ou duplicou itens do draft.');

$pdo->prepare('UPDATE products SET price_cents=2200 WHERE id=? AND tenant_id=?')->execute([$burgerId,$tenantId]);$send('meu pedido');$q=$pdo->prepare('SELECT unit_price_cents,total_cents FROM order_items WHERE order_id=? ORDER BY id LIMIT 1');$q->execute([$draftId]);$repriced=$q->fetch(PDO::FETCH_ASSOC);wa1_assert((int)$repriced['unit_price_cents']===3400&&(int)$repriced['total_cents']===6800,'Carrinho não recalculou preço atual do servidor.');

// Adicional indisponível deve invalidar a linha sem aceitar preço/configuração antiga.
$pdo->prepare('UPDATE modifier_options SET active=0 WHERE id=? AND tenant_id=?')->execute([$cheese,$tenantId]);$send('meu pedido');$q=$pdo->prepare('SELECT total_cents FROM order_items WHERE order_id=? ORDER BY id LIMIT 1');$q->execute([$draftId]);wa1_assert((int)$q->fetchColumn()===0,'Adicional indisponível permaneceu válido no carrinho.');$pdo->prepare('UPDATE modifier_options SET active=1 WHERE id=? AND tenant_id=?')->execute([$cheese,$tenantId]);$send('meu pedido');$q=$pdo->prepare('SELECT unit_price_cents,total_cents FROM order_items WHERE order_id=? ORDER BY id LIMIT 1');$q->execute([$draftId]);$restored=$q->fetch(PDO::FETCH_ASSOC);wa1_assert((int)$restored['unit_price_cents']===3400&&(int)$restored['total_cents']===6800,'Carrinho não voltou a validar após restauração do adicional.');

$send('2');$send('1');$send('3');$q=$pdo->prepare('SELECT quantity,total_cents FROM order_items WHERE order_id=? ORDER BY id LIMIT 1');$q->execute([$draftId]);$resized=$q->fetch(PDO::FETCH_ASSOC);wa1_assert((int)$resized['quantity']===3&&(int)$resized['total_cents']===10200,'Alteração de quantidade não foi recalculada.');

$send('1');$send('1');wa1_assert(($send('1')['state']??'')==='SELECTING_QUANTITY','Produto simples deveria ir direto para quantidade.');$send('1');$send('0');$q=$pdo->prepare('SELECT COUNT(*) FROM order_items WHERE order_id=?');$q->execute([$draftId]);wa1_assert((int)$q->fetchColumn()===2,'Segundo item não foi adicionado.');
$pdo->prepare('UPDATE products SET active=0 WHERE id=? AND tenant_id=?')->execute([$drinkId,$tenantId]);$send('meu pedido');$q=$pdo->prepare('SELECT total_cents FROM order_items WHERE order_id=? AND product_id=?');$q->execute([$draftId,$drinkId]);wa1_assert((int)$q->fetchColumn()===0,'Produto desativado permaneceu valorizado no draft.');$send('3');$send('2');$q=$pdo->prepare('SELECT COUNT(*) FROM order_items WHERE order_id=? AND product_id=?');$q->execute([$draftId,$drinkId]);wa1_assert((int)$q->fetchColumn()===0,'Remoção de item não funcionou.');

$final=$send('4');wa1_assert(($final['state']??'')==='CHOOSING_FULFILLMENT','Finalizar carrinho não parou na fronteira da ETAPA 2.');$q=$pdo->prepare('SELECT status,channel,order_source,total_cents FROM orders WHERE id=?');$q->execute([$draftId]);$order=$q->fetch(PDO::FETCH_ASSOC);wa1_assert($order['status']==='draft'&&$order['channel']==='pending'&&$order['order_source']==='WHATSAPP','ETAPA 1 transformou indevidamente o draft em pedido operacional.');wa1_assert((int)$order['total_cents']===10200,'Total final do draft divergiu.');
$q=$pdo->prepare('SELECT COUNT(*) FROM payments WHERE tenant_id=? AND order_id=?');$q->execute([$tenantId,$draftId]);wa1_assert((int)$q->fetchColumn()===0,'ETAPA 1 criou pagamento.');$q=$pdo->prepare('SELECT COUNT(*) FROM stock_reservations WHERE tenant_id=? AND order_id=?');$q->execute([$tenantId,$draftId]);wa1_assert((int)$q->fetchColumn()===0,'ETAPA 1 reservou estoque antes da finalização operacional.');$q=$pdo->prepare('SELECT COUNT(*) FROM production_jobs WHERE tenant_id=? AND order_id=?');$q->execute([$tenantId,$draftId]);wa1_assert((int)$q->fetchColumn()===0,'ETAPA 1 criou produção/impressão.');

$requiredAudit=['whatsapp.customer_identified','whatsapp.draft_created','whatsapp.item_added','whatsapp.item_quantity_changed','whatsapp.item_removed','whatsapp.cart_finalized'];$q=$pdo->prepare('SELECT action,metadata FROM audit_logs WHERE tenant_id=? AND action LIKE "whatsapp.%"');$q->execute([$tenantId]);$auditRows=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$actions=array_values(array_unique(array_map(fn(array$r)=>(string)$r['action'],$auditRows)));foreach($requiredAudit as$action)wa1_assert(in_array($action,$actions,true),'Auditoria obrigatória ausente: '.$action);foreach($auditRows as$row)wa1_assert(!str_contains(mb_strtolower((string)($row['metadata']??'')),'sem cebola'),'Texto de observação do cliente vazou para audit_logs.');

